function imageAttrs(src,sizes){const m=C.media?.[src];return m?`width="${m.width}" height="${m.height}" srcset="${m.srcset}" sizes="${sizes}" decoding="async"`:'decoding="async"'}
document.querySelectorAll('[data-brand]').forEach(el=>el.textContent=C.brand);document.title=`${C.brand} — Ideas deserve a bigger orbit`;
for(const [id,value] of Object.entries({'tagline':C.tagline,'intro':C.intro,'work-title':C.workTitle,'work-intro':C.workIntro,'global-title':C.globalTitle,'global-intro':C.globalIntro,'contact-title':C.contactTitle,'contact-intro':C.contactIntro}))$('#'+id).textContent=value;
C.hero.forEach(t=>{const s=document.createElement('span');s.textContent=t;$('#headline').append(s)});$('#email-link').textContent=C.email;$('#email-link').href='mailto:'+C.email;$('#phone-link').textContent=C.phone;$('#phone-link').href=C.phoneHref;$('#year').textContent=new Date().getFullYear();
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});
function projectCover(p){if(!p.cover)return `<img src="${p.image}" alt="${p.title} project screenshot" loading="lazy" ${imageAttrs(p.image,'(max-width: 500px) 90vw, 43vw')}>`;const c=p.cover;return `<span class="app-cover ${c.theme}" aria-label="${p.title} app cover"><span class="cover-grid"></span><span class="cover-orbit"></span><span class="cover-label">${c.label}</span><span class="cover-phone"><img src="${p.images[0]}" alt="${p.title} first app screen" loading="lazy" ${imageAttrs(p.images[0],'(max-width: 500px) 145px, (max-width: 800px) 100px, 165px')}></span><span class="cover-wordmark">${c.subtitle}</span><span class="cover-title">${c.title}</span><span class="cover-note">${c.note}</span><span class="cover-chip">MOBILE EXPERIENCE ↗</span></span>`}
function renderProjects(filter='All'){$('#projects').replaceChildren();C.projects.forEach((p,i)=>{if(filter!=='All'&&p.type!==filter)return;const el=document.createElement('article');el.className='project reveal '+(p.type==='Mobile app'?'app':'');el.style.setProperty('--card',p.color);el.innerHTML=`<button class="project-visual" aria-label="Explore ${p.title}">${projectCover(p)}<span class="view">↗</span></button><div class="project-meta"><h3>${p.title}</h3><span>${p.type} / ${p.sector}</span></div><p>${p.description}</p><div class="project-links"><button class="text-button">Explore project ↗</button>${p.url?`<a class="live-link" href="${p.url}" target="_blank" rel="noopener noreferrer">${p.linkLabel} ↗</a>`:''}</div>`;el.querySelectorAll('button').forEach(b=>b.onclick=()=>openProject(i));$('#projects').append(el);observer.observe(el)})}renderProjects();
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});renderProjects(b.dataset.filter)});
function openProject(i){
 const p=C.projects[i], dialog=$('#project-dialog');
 $('#dialog-content').innerHTML=`<div class="project-intro"><span class="eyebrow">${p.type} · ${p.place}</span><h2>${p.title}</h2><p>${p.description}</p><p>${p.details}</p>${p.url?`<a class="live-link" href="${p.url}" target="_blank" rel="noopener noreferrer">${p.linkLabel} ↗</a>`:''}</div><div class="carousel" role="region" aria-roledescription="carousel" aria-label="${p.title} screenshots"><div class="carousel-track" tabindex="0" aria-label="Screenshot slides. Use left and right arrow keys to navigate.">${p.images.map((src,j)=>`<figure class="carousel-slide" role="group" aria-roledescription="slide" aria-label="${j+1} of ${p.images.length}"><img data-src="${src}" alt="${p.title} — screen ${j+1}" decoding="async" draggable="false"></figure>`).join('')}</div><div class="carousel-toolbar"><span class="carousel-hint">SWIPE OR DRAG TO EXPLORE</span><div class="carousel-controls"><button class="carousel-prev" aria-label="Previous screenshot">←</button><span class="carousel-count" aria-live="polite" aria-atomic="true">1 / ${p.images.length}</span><button class="carousel-next" aria-label="Next screenshot">→</button></div></div><div class="carousel-dots" role="group" aria-label="Choose screenshot">${p.images.map((_,j)=>`<button aria-label="Go to screenshot ${j+1}" aria-pressed="${j===0}" class="${j===0?'active':''}"></button>`).join('')}</div></div>`;
 const track=dialog.querySelector('.carousel-track'),slides=[...track.children],prev=dialog.querySelector('.carousel-prev'),next=dialog.querySelector('.carousel-next'),dots=[...dialog.querySelectorAll('.carousel-dots button')];let current=0;
 const loadSlide=j=>{const img=slides[j]?.querySelector('img[data-src]');if(!img)return;const src=img.dataset.src,m=C.media?.[src];if(m){img.width=m.width;img.height=m.height;img.sizes='(max-width: 1150px) 85vw, 1040px';img.srcset=m.srcset}img.src=src;delete img.dataset.src};
 const update=()=>{current=Math.max(0,Math.min(slides.length-1,Math.round(track.scrollLeft/track.clientWidth)));dialog.querySelector('.carousel-count').textContent=`${current+1} / ${slides.length}`;loadSlide(current);loadSlide(current+1);prev.disabled=current===0;next.disabled=current===slides.length-1;dots.forEach((dot,j)=>{dot.classList.toggle('active',j===current);dot.setAttribute('aria-pressed',j===current)})};
 const go=j=>{const target=Math.max(0,Math.min(slides.length-1,j));loadSlide(target);track.scrollTo({left:target*track.clientWidth,behavior:reduced?'instant':'smooth'})};
 prev.onclick=()=>go(current-1);next.onclick=()=>go(current+1);dots.forEach((dot,j)=>dot.onclick=()=>go(j));track.addEventListener('scroll',update,{passive:true});track.onkeydown=e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();go(current+(e.key==='ArrowRight'?1:-1))}else if(e.key==='Home'||e.key==='End'){e.preventDefault();go(e.key==='Home'?0:slides.length-1)}};
 let pointer=null,startX=0,startScroll=0;
 track.onpointerdown=e=>{if(e.pointerType!=='mouse'||e.button!==0)return;pointer=e.pointerId;startX=e.clientX;startScroll=track.scrollLeft;track.setPointerCapture(e.pointerId);track.classList.add('dragging')};
 track.onpointermove=e=>{if(pointer===e.pointerId)track.scrollLeft=startScroll-(e.clientX-startX)};
 const release=e=>{if(pointer!==e.pointerId)return;const delta=e.clientX-startX;track.classList.remove('dragging');pointer=null;const startIndex=Math.round(startScroll/track.clientWidth);go(Math.abs(delta)>40?startIndex+(delta<0?1:-1):startIndex)};
 track.onpointerup=release;track.onpointercancel=e=>{pointer=null;track.classList.remove('dragging');go(current)};
 dialog.showModal();dialog.scrollTop=0;update();
}
$('.close').onclick=()=>$('#project-dialog').close();$('#project-dialog').onclick=e=>{if(e.target===$('#project-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}};
C.services.forEach(([n,t,d])=>{const e=document.createElement('div');e.className='service reveal';e.innerHTML=`<span>${n}</span><h3>${t}</h3><p>${d}</p>`;$('#services').append(e);observer.observe(e)});
document.querySelectorAll('.section-heading,h2,.contact-copy').forEach(e=>{e.classList.add('reveal');observer.observe(e)});
if(!reduced){let queued=false;addEventListener('scroll',()=>{if(!queued){requestAnimationFrame(()=>{const y=scrollY;$('.orb-art').style.transform=`translateY(${Math.min(y*.18,140)}px) rotate(${-18+y*.025}deg)`;queued=false});queued=true}},{passive:true});$('.orb-art').addEventListener('pointermove',e=>{const r=e.currentTarget.getBoundingClientRect();e.currentTarget.style.transform=`rotate(-18deg) rotateY(${(e.clientX-r.left-r.width/2)*.04}deg)`})}
// Orthographic 3D projection. All six market locations come from content.js.
const canvas=$('#globe'),ctx=canvas.getContext('2d');let angle=-.75,drag=false,lastX=0,selected=-1,pauseUntil=0;
const lands=[ [[-168,68],[-140,70],[-125,55],[-124,40],[-110,25],[-98,18],[-84,22],[-80,30],[-65,47],[-55,54],[-83,65],[-110,72]], [[-81,12],[-65,9],[-48,-1],[-35,-9],[-43,-24],[-67,-55],[-76,-30]], [[-18,36],[1,37],[14,32],[34,31],[51,12],[42,-12],[31,-33],[17,-35],[10,-14],[-1,5],[-17,15]], [[-10,36],[-10,58],[8,71],[30,70],[42,55],[30,40],[15,35]], [[30,40],[40,60],[70,75],[120,72],[170,65],[150,49],[130,43],[120,20],[103,1],[80,8],[70,25],[50,12],[36,30]], [[112,-11],[135,-11],[153,-26],[146,-39],[116,-34]], [[-52,60],[-43,60],[-20,78],[-44,83],[-60,76]], [[46,-13],[50,-16],[48,-25],[44,-23]] ];
function inside(x,y,poly){let v=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const a=poly[i],b=poly[j];if((a[1]>y)!=(b[1]>y)&&x<(b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0])v=!v}return v}
const dots=[];for(let lat=-55;lat<80;lat+=3.2)for(let lon=-178;lon<180;lon+=3.2)if(lands.some(p=>inside(lon,lat,p)))dots.push([lat,lon]);
C.markets.forEach(([name],i)=>{const b=document.createElement('button');b.textContent=name;b.onclick=()=>{selected=i;angle=-C.markets[i][2]*Math.PI/180;pauseUntil=performance.now()+9000;document.querySelectorAll('.markets button').forEach((el,j)=>{el.classList.toggle('active',j===i);el.setAttribute('aria-pressed',j===i)});draw()};$('#markets').append(b)});
function project(lat,lon,r,cx,cy){const a=lat*Math.PI/180,b=lon*Math.PI/180+angle;return [cx+r*Math.cos(a)*Math.sin(b),cy-r*Math.sin(a),Math.cos(a)*Math.cos(b)]}
function draw(){const rect=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio,2);if(canvas.width!==Math.round(rect.width*dpr)||canvas.height!==Math.round(rect.height*dpr)){canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr)}ctx.setTransform(dpr,0,0,dpr,0,0);const w=rect.width,h=rect.height,cx=w/2,cy=h/2,r=Math.min(w*.4,h*.43);ctx.clearRect(0,0,w,h);const g=ctx.createRadialGradient(cx-r*.3,cy-r*.35,0,cx,cy,r);g.addColorStop(0,'#3d4535');g.addColorStop(1,'#20261e');ctx.fillStyle=g;ctx.beginPath();ctx.arc(cx,cy,r,0,7);ctx.fill();ctx.strokeStyle='#65715655';ctx.lineWidth=.65;
for(let lat=-60;lat<=60;lat+=30){ctx.beginPath();let first=true;for(let lon=-180;lon<=180;lon+=3){const [x,y,z]=project(lat,lon,r,cx,cy);if(z>0){first?ctx.moveTo(x,y):ctx.lineTo(x,y);first=false}else first=true}ctx.stroke()}
for(let lon=-180;lon<180;lon+=30){ctx.beginPath();let first=true;for(let lat=-90;lat<=90;lat+=3){const [x,y,z]=project(lat,lon,r,cx,cy);if(z>0){first?ctx.moveTo(x,y):ctx.lineTo(x,y);first=false}else first=true}ctx.stroke()}
dots.forEach(([lat,lon])=>{const [x,y,z]=project(lat,lon,r,cx,cy);if(z<0)return;ctx.fillStyle=`rgba(181,196,151,${.25+z*.55})`;ctx.beginPath();ctx.arc(x,y,1.2,0,7);ctx.fill()});
C.markets.forEach(([name,lat,lon],i)=>{const [x,y,z]=project(lat,lon,r*1.015,cx,cy);if(z<.05)return;ctx.fillStyle='#ff5b3025';ctx.beginPath();ctx.arc(x,y,i===selected?15:10,0,7);ctx.fill();ctx.fillStyle='#ff6b3e';ctx.beginPath();ctx.arc(x,y,3.5,0,7);ctx.fill();ctx.fillStyle='#f3f1e9';ctx.font='10px sans-serif';ctx.fillText(name,x+10,y-8)});ctx.strokeStyle='#8c9a6c55';ctx.beginPath();ctx.ellipse(cx,cy,r*1.17,r*.35,-.3,0,Math.PI*2);ctx.stroke()}
canvas.onpointerdown=e=>{drag=true;lastX=e.clientX;canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(drag){angle+=(e.clientX-lastX)*.008;lastX=e.clientX;pauseUntil=performance.now()+3000;draw()}};canvas.onpointerup=canvas.onpointercancel=()=>drag=false;
let globeVisible=false,globeFrame=0,prev=0;
function tick(t){globeFrame=0;if(!globeVisible||document.hidden||reduced)return;if(t-prev>35){if(!drag&&t>pauseUntil)angle+=.002;draw();prev=t}globeFrame=requestAnimationFrame(tick)}
function syncGlobe(){if(globeFrame)cancelAnimationFrame(globeFrame);globeFrame=0;if(globeVisible&&!document.hidden){draw();if(!reduced)globeFrame=requestAnimationFrame(tick)}}
new IntersectionObserver(entries=>{globeVisible=entries[0].isIntersecting;syncGlobe()},{rootMargin:'100px'}).observe(canvas);
document.addEventListener('visibilitychange',syncGlobe);addEventListener('resize',()=>{if(globeVisible&&!document.hidden)draw()});
let toastTimer;
function showToast(message,kind='success'){
 const toast=$('#form-toast');clearTimeout(toastTimer);toast.dataset.kind=kind;toast.textContent=message;toast.hidden=false;
 toastTimer=setTimeout(()=>{toast.hidden=true},3000);
}
const enquiry=$('#enquiry'),status=$('#form-status');
enquiry.addEventListener('invalid',()=>{status.textContent='Please complete the required fields and enter a valid email address. Your project description needs at least 10 characters.';showToast('Please check the required form fields.','error')},true);
enquiry.addEventListener('submit',async e=>{
 e.preventDefault();const form=e.target,b=form.querySelector('.submit'),data=Object.fromEntries(new FormData(form));
 if(b.disabled)return;
 b.disabled=true;b.textContent='Sending…';form.setAttribute('aria-busy','true');status.textContent='Sending your project enquiry…';
 const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),15000);
 try{
  const response=await fetch('https://formsubmit.co/ajax/'+encodeURIComponent(C.email),{method:'POST',signal:controller.signal,headers:{'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify({...data,_subject:`${C.brand}: ${data.service} enquiry from ${data.name}`,_template:'table',_replyto:data.email})});
  const result=await response.json();
  if(!response.ok||!(result.success===true||result.success==='true'))throw Error('The email service did not confirm acceptance.');
  status.textContent='Your enquiry was submitted successfully. Thank you for getting in touch!';
  showToast('✓ Project enquiry submitted successfully!');form.reset();
 }catch(error){
  const message=error.name==='AbortError'?'We couldn’t confirm your submission. Please email us directly.':'Your enquiry could not be sent. Please try again or email us directly.';
  status.replaceChildren(document.createTextNode(message+' '));
  const a=document.createElement('a');a.href=`mailto:${C.email}?subject=${encodeURIComponent(C.brand+' project enquiry')}&body=${encodeURIComponent(`Name: ${data.name}\nEmail: ${data.email}\nService: ${data.service}\n\n${data.message}`)}`;a.textContent=C.email;status.append(a);showToast(message,'error');
 }finally{clearTimeout(timeout);b.disabled=false;b.innerHTML='Send project enquiry <span>↗</span>';form.removeAttribute('aria-busy')}
});

